INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('6a15f4a7-b4a2-4ab9-b504-f5ee8d82833e', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '16', 'Budget (spend-type table; $200,000 cap; Personnel <= $40,000)', '{"version":1,"document_id":"5c86b8b2-ca95-4b80-9d06-2e7436ba032e","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation — TVSF Budget","height":36,"font":{"family":"Times New Roman","size":10}},"footer":{"template":"Foundation — TVSF Application (confidential)","height":36,"font":{"family":"Times New Roman","size":10}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":null,"max_slides":null},"metadata":{"title":"Budget","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.510Z","last_modified_at":"2026-08-10T03:15:31.510Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"nb33f5ed2","type":"heading","content":{"level":1,"text":"Budget — Ohio Third Frontier TVSF"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n85845932","type":"text_block","content":{"text":"Project budget by spend type. The OTF ask is exactly $200,000; Personnel is within the 20% share cap; no applicant cost share is required or claimed."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n4006536f","type":"table","content":{"sheet_name":"Budget","is_spreadsheet":true,"headers":[{"text":"Spend Type","style":{"bold":true,"bg":"#2c3e7a","alignment":"center"}},{"text":"OTF Project Funds","style":{"bold":true,"bg":"#2c3e7a","alignment":"center"}},{"text":"Basis / Narrative","style":{"bold":true,"bg":"#2c3e7a","alignment":"center"}}],"rows":[[{"text":"Personnel","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$40,000","value":40000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"PI + engineering oversight across MS1–MS8 (balance funded by the pre-seed round); at the 20% cap"}],[{"text":"Equipment","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$55,000","value":55000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"Production printer / externally-gated nozzle / runway-rail trolley build (MS2–MS3)"}],[{"text":"Supplies","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$18,000","value":18000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"Concrete and print materials across the mix-latitude and full-print milestones (MS1, MS5)"}],[{"text":"Purchased Services","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$77,000","value":77000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"Independent third-party structural testing (MS6) + embedded/PCB support — fixed-price"}],[{"text":"Other Direct Costs","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$10,000","value":10000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"Shipping, calibration, and the MS8 performance-data package"}],[{"text":"Total OTF Project Funds","style":{"bold":true,"bg":"#2c3e7a"}},{"text":"$200,000","value":200000,"number_format":"$#,##0","cell_type":"currency","style":{"bold":true,"bg":"#2c3e7a","alignment":"right"}},{"text":"","style":{"bold":true,"bg":"#2c3e7a","alignment":"right"}}]],"column_widths":[150,110,270],"border_style":"single"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n71671ecc","type":"heading","content":{"level":2,"text":"Budget Compliance"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n90b86a8f","type":"table","content":{"is_spreadsheet":true,"headers":[{"text":"Metric","style":{"bold":true,"bg":"#2c3e7a","alignment":"center"}},{"text":"Value","style":{"bold":true,"bg":"#2c3e7a","alignment":"center"}},{"text":"Requirement","style":{"bold":true,"bg":"#2c3e7a","alignment":"center"}},{"text":"Status","style":{"bold":true,"bg":"#2c3e7a","alignment":"center"}}],"rows":[[{"text":"OTF Ask"},{"text":"$200,000","value":200000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"≤ $200,000"},{"text":"PASS","style":{"bold":true}}],[{"text":"Personnel Share"},{"text":"20.0%","value":0.2,"number_format":"0.0%","cell_type":"percent","style":{"alignment":"right"}},{"text":"≤ 20%"},{"text":"PASS","style":{"bold":true}}],[{"text":"Applicant Cost Share"},{"text":"$0","value":0,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"None required"},{"text":"PASS","style":{"bold":true}}]],"column_widths":[150,90,160,70],"border_style":"single"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n6f764867","type":"heading","content":{"level":2,"text":"Budget Narrative"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nc77b72ba","type":"text_block","content":{"text":"Personnel ($40,000) covers principal-investigator and engineering oversight across all eight milestones; the balance of the engineering effort is funded by Foundation’s concurrent pre-seed round, so the TVSF personnel line stays at the 20% cap. Equipment ($55,000) funds the production build of the printer, externally-gated nozzle, and runway-rail trolley (MS2–MS3). Supplies ($18,000) cover locally batched ready-mix and print materials for the mix-latitude testing (MS1) and the full lab print (MS5). Purchased Services ($77,000) — the largest line — funds independent third-party structural testing (MS6) and embedded/PCB engineering to optimize gate control, both on fixed-price terms. Other Direct Costs ($10,000) cover shipping, calibration, and publication of the MS8 performance-data package. Every line ties to a specific, verifiable milestone deliverable, and the fixed-price structure of the two largest external lines bounds overrun risk."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:32.160Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:32.160Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:32.160Z'::timestamptz, true, '2026-08-10T03:15:32.160Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Budget', 2, NULL, '{}', '{"itemType":"spreadsheet","volumeName":"Budget","expertNotes":null}'::jsonb, 'a9d36876-0bbf-4aa6-8151-c52a4fb05e64', 16, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('07c7881f-c5d4-473c-8911-d1f1da1bab2f', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '17', 'Willingness-to-License Letter (from the IP-owning institution)', '{"version":2,"document_id":"bb9cadbe-e599-4dfe-8d10-8ca666e486b9","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"Willingness-to-License Letter","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.524Z","last_modified_at":"2026-08-10T03:15:31.524Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"nabbc68b9","type":"heading","content":{"level":1,"text":"Ohio Institute for Advanced Construction"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n34098d64","type":"text_block","content":{"text":"Office of Technology Transfer  ·  Dayton, Ohio"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n7ad1417f","type":"text_block","content":{"text":"February 10, 2026"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n79d296a6","type":"text_block","content":{"text":"Ohio Third Frontier — Technology Validation and Startup Fund, Review Committee"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n2c397e17","type":"text_block","content":{"text":"Re: Willingness to License U.S. Patent No. 11,842,516 to Foundation, Inc."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nd43e298b","type":"text_block","content":{"text":"Dear Members of the Review Committee:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"ndbfe2226","type":"text_block","content":{"text":"The Ohio Institute for Advanced Construction (OIAC) is the owner of U.S. Patent No. 11,842,516, “Externally-Gated Nozzle and Layer-Control Method for Cementitious Additive Manufacturing” (issued March 2024), which covers the external material-flow gate and layer-control method at the core of Foundation’s residential 3D-printing system. This letter confirms OIAC’s willingness to license that technology to Foundation, Inc."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nca9a6a01","type":"text_block","content":{"text":"Through our Office of Technology Transfer we have negotiated, and are prepared to execute, a field-of-use exclusive license to Foundation for the residential concrete-foundation market. Foundation submitted a complete license application and commercialization plan, which our office reviewed and helped finalize; definitive terms are agreed in principle, and we anticipate executing the license within sixty (60) days of a TVSF award. The license grants Foundation exclusivity in the residential-foundation field of use, with diligence, reporting, and royalty provisions consistent with our office’s standard practice."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n2aa60033","type":"text_block","content":{"text":"We support this application for two reasons. First, Foundation’s team has demonstrated genuine technical command of the invention — printing full-height wall segments with the externally-gated nozzle using standard ready-mix concrete. Second, commercializing this patent through an Ohio company, with printers manufactured in Ohio, advances precisely the technology-to-market mission that our institute and the Ohio Third Frontier share."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nec250e86","type":"text_block","content":{"text":"OIAC endorses Foundation’s TVSF application without reservation and stands ready to execute the field-of-use license upon award."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"na3a5766a","type":"text_block","content":{"text":"Sincerely,"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n661be6bd","type":"text_block","content":{"text":"Director, Office of Technology Transfer · Ohio Institute for Advanced Construction"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:32.212Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:32.212Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:32.212Z'::timestamptz, true, '2026-08-10T03:15:32.212Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Supporting Letters', 3, NULL, '{}', '{"itemType":"pdf","volumeName":"Supporting Letters","expertNotes":null}'::jsonb, 'eb81dd40-50a9-4ef0-9d8e-9c955c1f87bd', 17, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('471ae084-702f-4060-8a24-66edb42818c0', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '18', 'ESP Support Letter (from the EC)', '{"version":2,"document_id":"d570cee8-5dce-4114-a04d-6592155197f8","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"ESP Support Letter","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.525Z","last_modified_at":"2026-08-10T03:15:31.525Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n8a9527a4","type":"heading","content":{"level":1,"text":"Dayton/Miami Valley Entrepreneurs Center"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n9dd6ca2e","type":"text_block","content":{"text":"Entrepreneurial Services Provider  ·  Dayton, Ohio"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n85e9f3d9","type":"text_block","content":{"text":"February 10, 2026"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n7b6930c5","type":"text_block","content":{"text":"Ohio Third Frontier — Technology Validation and Startup Fund, Review Committee"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n490912dd","type":"text_block","content":{"text":"Re: Entrepreneurial Services Provider Support for Foundation, Inc."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n6d5982c8","type":"text_block","content":{"text":"Dear Members of the Review Committee:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"na8de2d0d","type":"text_block","content":{"text":"The Dayton/Miami Valley Entrepreneurs Center (DMVEC) is Foundation’s Entrepreneurial Services Provider and has worked closely with the company since March 2025. We write in strong support of Foundation’s Technology Validation and Startup Fund application."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n91e299e7","type":"text_block","content":{"text":"Our engagement has been substantive, not advisory in name only. DMVEC helped Foundation design and run the customer-discovery program with production homebuilders and foundation subcontractors that produced the market evidence in this application; we built and stress-tested the financial model behind the company’s pro-forma and funding plan; and we advised directly on the scope, milestones, and budget of the proposed TVSF project. We meet with the founding team on a biweekly basis and have reviewed this application in full."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n4ee378ad","type":"text_block","content":{"text":"On that basis we can speak to both the opportunity and the team. Foundation’s 3D-printed-foundation technology addresses a real, quantified, and timely market need — the labor-intensive formwork cycle that adds hundreds of hours and thousands of dollars to every home. The founding team pairs a working printer with direct builder relationships and a credible Ohio-manufacturing plan, and it has been disciplined about validating before it scales. In our assessment the team is well-positioned to execute the proposed validation project and to commercialize the result in Ohio."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n95eba4bb","type":"text_block","content":{"text":"DMVEC endorses this application and will continue to support Foundation through award and into commercialization — including the pre-seed raise, field-demonstration site selection, and the conversion of discovery-stage relationships into paid pilots."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nf7b83047","type":"text_block","content":{"text":"Sincerely,"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"ne872d298","type":"text_block","content":{"text":"Director of Entrepreneurial Services · Dayton/Miami Valley Entrepreneurs Center"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:32.246Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:32.246Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:32.246Z'::timestamptz, true, '2026-08-10T03:15:32.246Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Supporting Letters', 3, NULL, '{}', '{"itemType":"pdf","volumeName":"Supporting Letters","expertNotes":null}'::jsonb, 'eb81dd40-50a9-4ef0-9d8e-9c955c1f87bd', 18, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('782cd6c7-9285-43de-bd39-247f812d2e40', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '2', '1. Market Opportunity (external only; state TAM; SAM/SOM; hyperlinks allowed here only)', '{"version":2,"document_id":"e8182c71-c937-4790-b977-072e854df14e","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"1. Market Opportunity (external only; state TAM; SAM/SOM; hyperlinks allowed here only)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.494Z","last_modified_at":"2026-08-10T03:15:31.494Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n8fccc19c","type":"heading","content":{"level":1,"text":"1. Market Opportunity"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n474b31d0","type":"text_block","content":{"text":"Every residential concrete foundation in the United States is formed with temporary wooden or aluminum formwork that must be built, set, stripped, repaired, and cleaned for reuse. On a typical 2,100 sq ft home this formwork cycle consumes roughly 336 labor hours and a meaningful share of the foundation budget, and it is a chronic source of schedule slip because it cannot proceed in poor weather. The pain is felt hardest by production homebuilders and foundation subcontractors, who face a persistent skilled-labor shortage and thin margins."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n1d5a51c1","type":"text_block","content":{"text":"Approximately 1.4 million new single-family homes are started in the U.S. each year, essentially all requiring a formed concrete foundation, and the current U.S. spend on residential formwork and foundation labor is estimated at over $23.7B annually. The addressable pain is the formwork portion of that spend — the build-strip-repair-clean cycle — which is precisely what a direct-printed wall eliminates."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n53372d4d","type":"text_block","content":{"text":"The problem is acute now for two converging reasons. First, the residential-construction trades face a structural skilled-labor shortage that raises cost and lengthens schedule on exactly the manual, weather-exposed work formwork represents. Second, persistent under-supply of entry-level housing has put builders and policymakers under real pressure to take cost and time out of the home. A method that removes ~311 labor hours and a large share of the formwork/material cost from every foundation — without asking the builder to change concrete supplier, code path, or crew skill profile — is therefore both economically compelling and timely."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.609Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.609Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.609Z'::timestamptz, true, '2026-08-10T03:15:31.609Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 2, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('5ba5ea4c-6cc6-4b03-8b6e-8619b831706b', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '3', '2. Overview of Technology/Product (native competitor comparison table)', '{"version":2,"document_id":"e0c4737e-bf48-4007-a44b-d7fddc6690d7","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"2. Overview of Technology/Product (native competitor comparison table)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.497Z","last_modified_at":"2026-08-10T03:15:31.497Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n8500a338","type":"heading","content":{"level":1,"text":"2. Overview of Technology/Product"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"ncf9bd286","type":"text_block","content":{"text":"Foundation’s system prints a home’s foundation-wall geometry directly: a build plan is downloaded to the printer, concrete is pumped into the machine, and the nozzle lays concrete one layer at a time while a printing trolley moves laterally and vertically along runway rails. Two differentiators define the product. First, it uses common, locally sourced concrete rather than an expensive proprietary mortar — the single largest cost and supply-chain constraint on competing printers. Second, an external gate controls material flow at the nozzle, enabling clean starts and stops and consistent layers without the smearing and cold-joint defects that plague mortar-extrusion systems. The net effect eliminates the build-strip-repair-clean formwork cycle, cutting foundation labor from ~336 hours to ~25 and formwork/material cost by 47–65% versus both conventional forming and mortar-based concrete printers."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nde301280","type":"table","content":{"headers":[{"text":"Performance factor"},{"text":"Foundation"},{"text":"Conventional formwork"},{"text":"Mortar-extrusion printers"}],"rows":[[{"text":"Common local concrete (no proprietary mortar)"},{"text":"✓"},{"text":"✓"},{"text":"✗"}],[{"text":"Clean starts/stops (external gate)"},{"text":"✓"},{"text":"n/a"},{"text":"✗"}],[{"text":"Eliminates form build-strip-clean cycle"},{"text":"✓"},{"text":"✗"},{"text":"✓"}],[{"text":"Foundation labor hours (2,100 sq ft)"},{"text":"~25"},{"text":"~336"},{"text":"~120"}],[{"text":"Formwork + material cost vs conventional"},{"text":"−47–65%"},{"text":"baseline"},{"text":"−10–20%"}]]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n0b3289d5","type":"text_block","content":{"text":"The external gate is the technical heart of the product and the reason Foundation can use common concrete. In conventional mortar-extrusion printers, flow is controlled only by the pump, so every start and stop smears material and every layer boundary risks a cold joint — which is why those systems must use an expensive, tightly-specified proprietary mortar to stay printable. Foundation’s gate mechanically opens and closes the material stream at the nozzle independently of the pump, producing clean starts and stops and consistent layer height with ordinary, locally batched ready-mix. That single design choice is what collapses both the cost curve and the supply-chain constraint at the same time, and it is the subject of the licensed patent (Q5)."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.660Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.660Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.660Z'::timestamptz, true, '2026-08-10T03:15:31.660Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 3, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('fd8f5843-85df-45c3-81c8-3cb5104d2269', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '4', '3. Development Stage & Timeline (native Gantt/timeline table; state TRL)', '{"version":2,"document_id":"1e55b06d-ae67-455f-885d-cd5fa40142c1","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"3. Development Stage & Timeline (native Gantt/timeline table; state TRL)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T11:05:18.334Z","last_modified_at":"2026-08-10T11:05:18.334Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n4923ac1c","type":"heading","content":{"level":1,"text":"3. Development Stage and Timeline"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n70ea9664","type":"text_block","content":{"text":"The core printing system is beyond proof-of-concept. Foundation has printed full-height wall segments with the runway-rail trolley and the external-gate nozzle using standard ready-mix concrete, validating the layer geometry and clean start/stop behavior that differentiate the product (TRL 5–6). The customer requirement driving the current MVP came directly from production-builder interviews: a printer that runs on locally batched concrete and produces an inspection-ready footing-to-top-of-wall in a single setup. This TVSF project takes the system to a manufacture-ready configuration and a fully instrumented field demonstration."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nf7a345f0","type":"text_block","content":{"text":"The 12-month plan is shown as the Gantt below and maps one-for-one to the Q11 milestone table; time to first commercial installation is estimated at 14 months from award."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"ncdc506d9","type":"chart","content":{"chart_type":"gantt","categories":["MS1 Concrete-mix latitude","MS2 Nozzle/gate (mfg-ready)","MS3 Trolley/runway build","MS4 Build-plan pipeline","MS5 Full print (lab)","MS6 Structural testing","MS7 Field demonstration","MS8 Data package"],"series":[{"name":"Start month","data":[1,2,3,4,5,6,9,11]},{"name":"End month","data":[2,3,4,5,7,9,11,12]}],"title":"TVSF 12-Month Project Gantt (MS1–MS8)"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n645373f7","type":"caption","content":{"prefix":"Figure","number":"1","text":"TVSF 12-month project Gantt — each milestone MS1–MS8 plotted by month, mapping one-for-one to the Q11 Project Plan table."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T11:12:56.800Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T11:12:56.800Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T11:12:56.800Z'::timestamptz, true, '2026-08-10T11:12:56.800Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 4, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('dc9be2c3-45b6-4050-914f-aa203834ae62', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '1', 'Abstract (public; excluded from 7-page count; no trade secrets)', '{"version":2,"document_id":"9f55b03c-53e2-4bab-98da-d8df145a60f1","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"Abstract (public; excluded from 7-page count; no trade secrets)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.491Z","last_modified_at":"2026-08-10T03:15:31.491Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"nff23cd3a","type":"heading","content":{"level":1,"text":"Abstract"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n6deb189d","type":"text_block","content":{"text":"Residential foundations are still built the way they were a century ago: crews set and strip wooden or aluminum formwork, pour concrete, wait, then repair and clean — a labor-intensive, weather-exposed cycle that adds roughly 336 hours and thousands of dollars to every home. Foundation 3D-prints the foundation wall directly from a downloaded build plan, using common, locally sourced concrete instead of expensive proprietary mortar and an external material-flow gate that produces clean starts, stops, and consistent layers. Foundation is an Ohio company commercializing this printer for the U.S. residential-construction market. This TVSF project validates a production-ready printer and delivers third-party performance data that de-risks a $23.7B U.S. formwork opportunity while advancing Ohio’s housing-affordability and advanced-manufacturing agendas."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.550Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.550Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.550Z'::timestamptz, true, '2026-08-10T03:15:31.550Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 1, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('f215c8fa-9750-4e3e-bfa7-4070b387ec38', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '5', '4. Commercialization Strategy (open with the SAM)', '{"version":2,"document_id":"91829ea2-5776-4374-a885-70dea7992dee","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"4. Commercialization Strategy (open with the SAM)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.499Z","last_modified_at":"2026-08-10T03:15:31.499Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n2d4ebb5f","type":"heading","content":{"level":1,"text":"4. Commercialization and Market Entry Strategy"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n0833ef1e","type":"text_block","content":{"text":"The residential-construction market adopts new methods cautiously and on evidence, but foundation subcontractors and production builders are actively seeking labor-saving methods because of the skilled-labor shortage. Foundation’s initial target customer is the regional production homebuilder and its foundation subcontractor in high-volume Sunbelt and Midwest markets, where repeatable floor plans make printed foundations especially efficient."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nbd4d09f7","type":"text_block","content":{"text":"Go-to-market is a printer-plus-service model: Foundation places printers with foundation subcontractors under a lease-plus-per-linear-foot arrangement, with training and remote build-plan support. Foundation has held discovery conversations with regional builders and foundation subs who have confirmed the labor and schedule pain and a willingness to pilot. This answer works in concert with the Q6 business model and the Q7 financial stage; the market-size argument is established in Q1 and is not repeated here."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n273d3055","type":"text_block","content":{"text":"Adoption follows a deliberate three-stage path that matches how the market actually buys. Stage one is the MS7 field demonstration plus the two standing letters of intent — a printed, inspector-signed foundation a builder can walk. Stage two is a small number of paid pilots on repeatable production floor plans, where the lease-plus-usage model lets a subcontractor try the printer with no capital outlay. Stage three is fleet expansion with the same builders as printed foundations become the default on their high-volume plans. Because Foundation sells a service rather than a machine, the buyer’s decision is an operating one, not a capital one — the single biggest lever on adoption speed in a conservative trade."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.742Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.742Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.742Z'::timestamptz, true, '2026-08-10T03:15:31.742Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 5, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('479950eb-7624-440f-b4f2-952659dab92b', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '6', '5. Intellectual Property (licensed IP + compare vs alternatives)', '{"version":2,"document_id":"d7182e8f-bd1f-4792-bcc7-cdaff0478a44","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"5. Intellectual Property (licensed IP + compare vs alternatives)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.501Z","last_modified_at":"2026-08-10T03:15:31.501Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n71664019","type":"heading","content":{"level":1,"text":"5. IP Position"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"na6d60029","type":"text_block","content":{"text":"The technology that is the subject of this TVSF application is protected by a field-of-use exclusive license to a patent owned by the Ohio Institute for Advanced Construction (OIAC), covering the external material-flow gate and layer-control method for cementitious printing (U.S. Patent No. 11,842,516, “Externally-Gated Nozzle and Layer-Control Method for Cementitious Additive Manufacturing,” issued March 2024). Foundation has submitted its license application and commercialization plan to OIAC’s Office of Technology Transfer, which has assisted in finalizing terms; a definitive field-of-use exclusive agreement for residential concrete foundations is anticipated within 60 days of award. The willingness-to-license letter accompanying this application confirms OIAC’s commitment."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n5504f283","type":"text_block","content":{"text":"This IP protects the core differentiator — clean, defect-free layers using common, locally sourced concrete — against the proprietary-mortar and mortar-extrusion approaches every competing printer relies on. A freedom-to-operate review by Foundation’s patent counsel found no blocking claims in the residential-foundation field of use. In addition, Foundation holds two of its own provisional filings — on the runway-rail trolley kinematics and on the build-plan-to-print-path software pipeline — which it will convert to non-provisional applications during the project, building a defensible portfolio around the licensed core."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.779Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.779Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.779Z'::timestamptz, true, '2026-08-10T03:15:31.779Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 6, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('1b156bfb-6e68-4601-a37d-1875c3874e98', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '7', '6. Business Model & Pro-forma P&L (native table 2027-2031; mandatory TVSF revenue row)', '{"version":2,"document_id":"8376a459-6eaa-45fa-87bb-382d8379fd4d","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"6. Business Model & Pro-forma P&L (native table 2027-2031; mandatory TVSF revenue row)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.502Z","last_modified_at":"2026-08-10T03:15:31.502Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"ncd9d908a","type":"heading","content":{"level":1,"text":"6. Business Model"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n8363919d","type":"text_block","content":{"text":"Foundation generates revenue two ways: printer leases to foundation subcontractors (recurring monthly), and a per-linear-foot build fee tied to each printed foundation (usage-based). Hardware is deliberately not sold outright — the lease-plus-usage model lowers the customer’s adoption barrier and gives Foundation a recurring, expanding revenue base as each printer prints more homes. R&D remains focused on print speed, concrete-mix latitude, and multi-story capability. The abbreviated pro-forma below uses the required TVSF categories without modification; figures are directional and in $1,000s."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nfbf99f59","type":"table","content":{"headers":[{"text":"($1,000s)"},{"text":"2027"},{"text":"2028"},{"text":"2029"},{"text":"2030"},{"text":"2031"}],"rows":[[{"text":"Revenues"},{"text":""},{"text":""},{"text":""},{"text":""},{"text":""}],[{"text":"  Product sales (printers)"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"}],[{"text":"  Licensing"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"}],[{"text":"  Printer lease + build fee"},{"text":"120"},{"text":"900"},{"text":"3,400"},{"text":"9,200"},{"text":"21,000"}],[{"text":"  Other"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"}],[{"text":"  Total revenues"},{"text":"120"},{"text":"900"},{"text":"3,400"},{"text":"9,200"},{"text":"21,000"}],[{"text":"Production Expenses"},{"text":""},{"text":""},{"text":""},{"text":""},{"text":""}],[{"text":"  Cost of Goods Sold"},{"text":"90"},{"text":"520"},{"text":"1,600"},{"text":"3,900"},{"text":"8,200"}],[{"text":"  Gross profit"},{"text":"30"},{"text":"380"},{"text":"1,800"},{"text":"5,300"},{"text":"12,800"}],[{"text":"Other Expenses"},{"text":""},{"text":""},{"text":""},{"text":""},{"text":""}],[{"text":"  R & D, including IP"},{"text":"600"},{"text":"900"},{"text":"1,300"},{"text":"1,800"},{"text":"2,400"}],[{"text":"  Sales, General & Admin."},{"text":"350"},{"text":"700"},{"text":"1,400"},{"text":"2,600"},{"text":"4,300"}],[{"text":"  Total other expenses"},{"text":"950"},{"text":"1,600"},{"text":"2,700"},{"text":"4,400"},{"text":"6,700"}],[{"text":"Net profit"},{"text":"(920)"},{"text":"(1,220)"},{"text":"(900)"},{"text":"900"},{"text":"6,100"}],[{"text":"Equity Investment"},{"text":"1,500"},{"text":"3,000"},{"text":"0"},{"text":"0"},{"text":"0"}]]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nd99bb9f4","type":"chart","content":{"chart_type":"line","categories":["2027","2028","2029","2030","2031"],"series":[{"name":"Total revenues","data":[120,900,3400,9200,21000],"color":"#3b82f6"},{"name":"Gross profit","data":[30,380,1800,5300,12800],"color":"#10b981"}],"title":"Pro-Forma Revenue & Gross Profit, 2027–2031 ($1,000s)"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n9c55c5ca","type":"caption","content":{"prefix":"Figure","number":"2","text":"Foundation pro-forma revenue and gross-profit ramp, 2027–2031 ($1,000s) — the recurring lease-plus-build-fee model."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"na261bcb9","type":"text_block","content":{"text":"The unit economics compound as the fleet matures. A single printer on lease plus per-linear-foot build fees generates recurring revenue from day one and pays back its manufacturing cost within its first full year of utilization; each additional printer added to a subcontractor’s operation raises Foundation’s revenue with little incremental overhead, which is why gross profit turns positive in the second year and margin expands thereafter. Revenue is intentionally shown as printer-lease-plus-build-fee only — no printer sales and no licensing income — so the pro-forma reflects the recurring core of the business, and the model reaches sustained net profitability by 2031."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.820Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.820Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.820Z'::timestamptz, true, '2026-08-10T03:15:31.820Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 7, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('7ee6cde2-9451-47e3-87b3-b36100bb1c00', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '9', '8. Economic Impact on Ohio', '{"version":2,"document_id":"4e044462-f7af-4752-a113-68e2ab93c272","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"8. Economic Impact on Ohio","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.504Z","last_modified_at":"2026-08-10T03:15:31.504Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n6f96354f","type":"heading","content":{"level":1,"text":"8. Economic Impact on State of Ohio"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nd0e8d381","type":"text_block","content":{"text":"Foundation is headquartered in the Dayton region and will manufacture and assemble its printers in-state, drawing on Ohio’s advanced-manufacturing supply base for the trolley, runway rails, and gate assembly. Direct employment scales with the fleet: the Q6 model implies roughly 45 skilled Ohio jobs by 2031 — advanced-manufacturing assembly, embedded/controls engineering, and field-service technicians — most of them outside the traditional four-year-degree track and well-matched to Ohio’s workforce."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"ne64cc194","type":"text_block","content":{"text":"The larger impact is on housing. By cutting foundation labor from ~336 hours to ~25 and formwork/material cost by 47–65%, a printed foundation removes several thousand dollars and days of schedule from every home — a direct contribution to Ohio’s housing-affordability agenda at a moment of acute shortage of entry-level supply. Commercializing the technology in Ohio also anchors a construction-technology cluster around the licensed OIAC IP, keeping the value chain — IP, manufacturing, and the first reference installations — inside the state."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.906Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.906Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.906Z'::timestamptz, true, '2026-08-10T03:15:31.906Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 9, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('7b42367a-9fa4-4055-a9c5-128c77c48563', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '12', '11. Project Plan (native milestone table: Name/Desc/Timeframe/Funds/Vendor; funds sum to ask)', '{"version":2,"document_id":"8fdfc3d1-0392-4f46-b707-cdbc3c4659ac","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"11. Project Plan (native milestone table: Name/Desc/Timeframe/Funds/Vendor; funds sum to ask)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.506Z","last_modified_at":"2026-08-10T03:15:31.506Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n5330ab05","type":"heading","content":{"level":1,"text":"11. Project Plan"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n4aa897df","type":"text_block","content":{"text":"The 12-month TVSF effort takes the printer to a manufacture-ready configuration and delivers an instrumented, inspection-ready field demonstration with third-party performance data. Milestones are measurable and map one-for-one to the Q3 Gantt."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nf3a63df1","type":"table","content":{"headers":[{"text":"Milestone"},{"text":"Description / Success Criteria"}],"rows":[[{"text":"MS1 — Concrete-mix latitude"},{"text":"Validate printing across 3 locally batched ready-mix designs; layer adhesion meets spec."}],[{"text":"MS2 — Manufacture-ready nozzle/gate"},{"text":"Externally-gated nozzle finalized for production; clean start/stop verified over 200 cycles."}],[{"text":"MS3 — Trolley/runway production build"},{"text":"Production runway-rail trolley assembled and calibrated to ±3mm placement."}],[{"text":"MS4 — Build-plan pipeline"},{"text":"Foundation-plan → print-path software validated on 5 production floor plans."}],[{"text":"MS5 — Full foundation print (lab)"},{"text":"Print a complete footing-to-top-of-wall foundation in a single setup."}],[{"text":"MS6 — Third-party structural testing"},{"text":"Independent lab confirms compressive/flexural performance vs code minimums."}],[{"text":"MS7 — Field demonstration"},{"text":"Print an inspection-ready foundation at a partner builder site; local inspector sign-off."}],[{"text":"MS8 — Performance data package"},{"text":"Publish labor-hour, cost, and quality data package for commercialization."}]]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"na03997de","type":"text_block","content":{"text":"The plan is sequenced around two go/no-go decision points that protect the award. The first, at the end of MS4, confirms the printer is manufacture-ready before any field commitment; the second, at MS6, requires the independent structural results to meet code minimums before the field demonstration proceeds. Foundation’s service providers (independent structural lab, embedded/PCB house, and machine shop) are contracted on a fixed-price basis against these milestones, so schedule and budget risk are bounded. Each milestone has a written acceptance criterion, and progress is reported to DMVEC and the review committee at the two decision gates."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:32.019Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:32.019Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:32.019Z'::timestamptz, true, '2026-08-10T03:15:32.019Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 12, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('242cb813-d082-48f5-b228-782075e9fc79', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '10', '9. Management Team (highest-weighted; names, FTE %, $ raised across ventures)', '{"version":2,"document_id":"4baad76b-228b-454f-984d-906203b4c12a","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"9. Management Team (highest-weighted; names, FTE %, $ raised across ventures)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T11:05:18.339Z","last_modified_at":"2026-08-10T11:05:18.339Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n837d5c18","type":"heading","content":{"level":1,"text":"9. Management Team"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nda4235fb","type":"text_block","content":{"text":"Foundation is led by people who have already reduced the core invention to practice and who have direct lines into how residential foundations are bought and inspected:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n055d8511","type":"bulleted_list","content":{"items":[{"text":"Marcus T. Reyes, Chief Executive Officer — 15 years in construction robotics; previously led gantry-robot development at a precast-concrete manufacturer. Drove Foundation’s printer architecture and the external-gate nozzle from concept to full-height wall prints."},{"text":"Dr. Priya Anand, Chief Technology Officer — PhD in civil/materials engineering (cementitious rheology) with 10 years across motion control and concrete mix design. Owns the concrete-mix latitude and the runway-rail trolley kinematics."},{"text":"Ryan Delacroix, VP Commercialization — 12 years in residential building-products go-to-market and former regional sales director at a foundation-systems supplier. Runs the builder and subcontractor discovery and pilot pipeline."},{"text":"Thomas Beckett, Advisor — President of Beckett Homes, an Ohio production homebuilder (~600 homes/year); advises on code path, buyer economics, and field-demonstration siting."},{"text":"Dr. Susan Hargrove, P.E., Advisor — licensed Ohio structural engineer, 20 years in residential foundation design; oversees the MS6 structural-test plan and inspection readiness."}]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n8a6684e2","type":"text_block","content":{"text":"The team is deliberately weighted toward the two capabilities this stage demands. Reyes and Anand have together taken the printer from concept to full-height wall prints, so the technical risk sits with people who have already retired much of it; Delacroix, Beckett, and Hargrove give Foundation a direct line into how foundations are actually bought and inspected. Foundation will hire a manufacturing/operations lead during the project, funded by the pre-seed round, to own the Ohio assembly line. A working printer, named builder and structural-engineer advisors, and Ohio manufacturing intent are the core of Foundation’s execution-risk mitigation — the highest-weighted TVSF review criterion."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T11:05:19.017Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T11:05:19.017Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T11:05:19.017Z'::timestamptz, true, '2026-08-10T11:05:19.017Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 10, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('e0a6c3eb-04c7-4ca6-96e4-b6edd232b5c8', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '15', '14. Major Risks & Mitigation (native Risk table: Risk/Type/Severity/Mitigation)', '{"version":2,"document_id":"c1dad385-0062-4cd8-9244-86f95f87d8a5","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"14. Major Risks & Mitigation (native Risk table: Risk/Type/Severity/Mitigation)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T11:05:18.341Z","last_modified_at":"2026-08-10T11:05:18.341Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"nef41fd40","type":"heading","content":{"level":1,"text":"14. Major Risks and Mitigation"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nba0fc939","type":"text_block","content":{"text":"Foundation has structured the project so its principal risks are retired early and by evidence rather than assertion. The highest-consequence risks, their type and severity, and the specific mitigation:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nc3cf8122","type":"table","content":{"headers":[{"text":"Risk"},{"text":"Type"},{"text":"Severity"},{"text":"Mitigation"}],"rows":[[{"text":"Concrete-mix variability across regions"},{"text":"Technical"},{"text":"Medium"},{"text":"MS1 latitude testing across three locally batched ready-mix designs; the external gate tolerates mix variation."}],[{"text":"Code / inspection acceptance"},{"text":"Regulatory"},{"text":"High"},{"text":"MS6 third-party structural testing and MS7 inspector sign-off; Dr. Hargrove (P.E.) oversees the test plan."}],[{"text":"Subcontractor adoption inertia"},{"text":"Market"},{"text":"Medium"},{"text":"Lease-plus-usage model removes the capital barrier; the MS8 labor/cost data package quantifies the savings."}],[{"text":"Manufacturing scale-up"},{"text":"Supply chain"},{"text":"Low"},{"text":"Fixed-price service-provider commitments and Ohio-based assembly bound cost and schedule."}],[{"text":"Financing / dilution"},{"text":"Financial"},{"text":"Medium"},{"text":"The concurrent $1.5M pre-seed de-risks the plan; non-dilutive TVSF reduces the capital needed to reach revenue."}]]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"ncfc64e45","type":"text_block","content":{"text":"Taken together, every claim in this application is converted into third-party evidence within twelve months — a manufacture-ready printer, an independent structural-test report, an inspector-signed field demonstration, and a published labor/cost/quality data package. That evidence retires the technical, regulatory, and market risks in sequence and hands Foundation exactly the assets it needs to convert its two standing letters of intent into paid pilots. Foundation respectfully requests TVSF support to validate a technology that takes cost, labor, and schedule out of every home — built, licensed, and manufactured in Ohio."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T11:05:19.195Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T11:05:19.195Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T11:05:19.195Z'::timestamptz, true, '2026-08-10T11:05:19.195Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 15, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('5e2008fb-ef39-49c0-bab3-043bc29b48c8', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '11', '10. ESP Engagement (the Entrepreneurs Center)', '{"version":2,"document_id":"38d7109d-4ad4-4dfe-b2cb-c2e16b86b61b","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"10. ESP Engagement (the Entrepreneurs Center)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.505Z","last_modified_at":"2026-08-10T03:15:31.505Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n2aecc33e","type":"heading","content":{"level":1,"text":"10. ESP Engagement"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n333ddd29","type":"text_block","content":{"text":"Foundation has worked with the Dayton/Miami Valley Entrepreneurs Center (DMVEC) since March 2025 as its Entrepreneurial Services Provider. DMVEC has been substantively involved in three areas that shape this application: it structured and pressure-tested the customer-discovery program with production builders and foundation subcontractors that produced the market evidence in Q1 and Q4; it built and stress-tested the financial model behind the Q6 pro-forma and the Q7 funding plan; and it advised directly on the scope, milestones, and budget of this TVSF project."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"na76494ad","type":"text_block","content":{"text":"Foundation’s primary DMVEC contact is its Director of Entrepreneurial Services, who meets with the founding team biweekly and has reviewed this application in full. The engagement is ongoing through award and into commercialization — DMVEC will continue to support the pre-seed raise, the field-demonstration site selection (MS7), and the conversion of discovery-stage relationships into paid pilots. DMVEC’s support letter accompanies this application."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.985Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.985Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.985Z'::timestamptz, true, '2026-08-10T03:15:31.985Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 11, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('9248b6c0-1f10-400c-9899-2659ac4b87ca', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '8', '7. Current Financial Stage', '{"version":2,"document_id":"93e42403-6b86-4ffa-82e8-ddfa53b9e3c2","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"7. Current Financial Stage","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.503Z","last_modified_at":"2026-08-10T03:15:31.503Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n1ba822c3","type":"heading","content":{"level":1,"text":"7. Current Financial Stage"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"na0bc8c91","type":"text_block","content":{"text":"Foundation has raised $650,000 to date — $150,000 from the founders and $500,000 from an Ohio pre-seed fund — and has approximately nine months of operating runway at the current burn. The company is pre-revenue by design: it has deliberately held back commercial installation until the printer is manufacture-ready and independently validated, which is exactly what this TVSF project delivers. Two regional builders have signed non-binding letters of intent to pilot printed foundations once the MS7 field demonstration and MS8 performance data are complete."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n8db18e5c","type":"text_block","content":{"text":"The funding strategy is to pair the $200,000 TVSF award with a concurrent $1.5M pre-seed round (in diligence with two Ohio funds) to reach the first commercial installations, then raise a seed round on the strength of the third-party field-performance data this project produces. The Q6 pro-forma rests on three assumptions grounded in the discovery interviews: printer lease pricing of $4,500/month, a build fee of $28 per linear foot of printed foundation, and a utilization ramp from one printer in the first year to a small managed fleet by the fourth. TVSF non-dilutive funding is the pivotal input that converts a validated prototype into a leasable, revenue-generating product."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:31.862Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:31.862Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:31.862Z'::timestamptz, true, '2026-08-10T03:15:31.862Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 8, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('beee1b87-55bd-40d6-9316-214dfd105970', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '14', '13. Next Steps (no exit language)', '{"version":2,"document_id":"6187b08d-3335-4b9a-8817-f07398eb3245","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"13. Next Steps (no exit language)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.508Z","last_modified_at":"2026-08-10T03:15:31.508Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"na63c3b98","type":"heading","content":{"level":1,"text":"13. Next Steps"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nf8794697","type":"text_block","content":{"text":"Immediately upon award, Foundation will execute the field-of-use license from OIAC — the terms are already negotiated — locking exclusive access to the core IP, and issue fixed-price purchase orders to its service providers for the manufacture-ready build (MS1–MS4). In parallel it will close the concurrent $1.5M pre-seed round and confirm the partner-builder field-demonstration site so MS7 can proceed on schedule."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n883f11ea","type":"text_block","content":{"text":"On completion of the 12-month project, Foundation exits with a manufacture-ready printer, an independent structural-test report (MS6), an inspector-signed field demonstration (MS7), and a published labor/cost/quality data package (MS8). Those four assets convert the two standing letters of intent into paid pilots and anchor the seed raise — the path from this TVSF validation to first commercial installation is estimated at 14 months from award."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:32.079Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:32.079Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:32.079Z'::timestamptz, true, '2026-08-10T03:15:32.079Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 14, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('60f3e18c-1ebb-4395-a798-31320baf4c5d', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '13', '12. Budget: Table & Narrative (ask <= $200k; Personnel <= 20%; no cost share; narrate every line)', '{"version":2,"document_id":"84a3c228-a898-48a5-921a-e2d69e8df7a0","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.09,"max_pages":7,"max_slides":null},"metadata":{"title":"12. Budget: Table & Narrative (ask <= $200k; Personnel <= 20%; no cost share; narrate every line)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T03:15:31.507Z","last_modified_at":"2026-08-10T03:15:31.507Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n4c46bd46","type":"heading","content":{"level":1,"text":"12. Budget: Table and Narrative"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n3e588084","type":"text_block","content":{"text":"Foundation’s $200,000 TVSF budget is presented in full in the Budget volume of this application. It has been vetted with Foundation’s service providers, who have committed to executing on a fixed-price basis to de-risk the project, and it is fully compliant with the TVSF Round-45 rules: the OTF ask is exactly $200,000, Personnel is held to the 20% cap ($40,000), and no applicant cost share is required or claimed."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nee3a1d07","type":"text_block","content":{"text":"Funds are concentrated on manufacture-ready hardware and independent validation. The largest line, $77,000 in purchased services, covers independent third-party structural testing (MS6) and embedded/PCB support to optimize gate control — both fixed-price. Equipment ($55,000) funds the production printer/nozzle/trolley build (MS2–MS3); supplies ($18,000) cover concrete and print materials across MS1 and MS5; and personnel ($40,000) covers principal-investigator and engineering oversight across MS1–MS8, with the balance of the engineering effort funded by the concurrent pre-seed round. Because the largest external line items are contracted on a fixed-price basis, the budget carries low overrun risk, and every dollar of TVSF funding is tied to a specific, verifiable milestone deliverable."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T03:15:32.050Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T03:15:32.050Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T03:15:32.050Z'::timestamptz, true, '2026-08-10T03:15:32.050Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 13, NULL) ON CONFLICT DO NOTHING;
